insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-so-186","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For an ideal solution the plot of $p_A$ versus $x_A$ is","options":["linear from 0 to $p_A^\\circ$","concave upward","concave downward","a horizontal line"],"answer_index":0,"explanation":"Raoult’s law $p_A = p_A^\\circ x_A$ is a straight line through the origin and $(1, p_A^\\circ)$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-187","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A liquid pair with $\\Delta V_{\\mathrm{mix}}$ negative and $p$ below the ideal line is classified as","options":["non-ideal with negative deviation","ideal","positively deviating","colloidal"],"answer_index":0,"explanation":"Volume contraction and lowered vapour pressure both point to stronger A–B attractions.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-188","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A binary liquid shows $\\Delta H_{\\mathrm{mix}}$ negative and total vapour pressure below the Raoult prediction at every composition. Distillation of this pair commonly yields","options":["a maximum-boiling azeotrope","a minimum-boiling azeotrope","an ideal vapour of unchanged composition","no condensate at any temperature"],"answer_index":0,"explanation":"Negative deviation produces a minimum in p versus x and therefore a maximum-boiling azeotrope.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-189","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Colligative properties of a dilute solution depend on","options":["the number of solute particles, not their chemical identity","the colour of the solute","the charge of the solute only","the solvent density only"],"answer_index":0,"explanation":"Particle count (mole fraction or molality) fixes the size of a colligative effect for a given solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-190","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Relative lowering of vapour pressure is defined as","options":["$(p^\\circ - p) / p^\\circ$","$p^\\circ - p$","$p / p^\\circ$","$p^\\circ / p$"],"answer_index":0,"explanation":"It is the fractional drop in solvent vapour pressure caused by the solute.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-191","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For a dilute solution of a non-volatile non-electrolyte, $(p^\\circ - p) / p^\\circ$ equals","options":["the mole fraction of the solute","the molality","the molarity","the mass percent"],"answer_index":0,"explanation":"Raoult’s law gives $(p^\\circ - p)/p^\\circ = x_{\\mathrm{solute}}$ in the dilute non-volatile limit.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-192","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The four classical colligative properties include relative lowering of vapour pressure, boiling-point elevation, freezing-point depression and","options":["osmotic pressure","viscosity","surface tension","refractive index"],"answer_index":0,"explanation":"Those four effects depend on the number of solute particles, not on their nature.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-193","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Relative lowering of vapour pressure does not depend on","options":["the chemical identity of a non-electrolyte solute","the mole fraction of that solute","the vapour pressure of the pure solvent","whether the solute is present at all"],"answer_index":0,"explanation":"Any non-volatile non-electrolyte at the same $x_B$ produces the same relative lowering.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-194","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A non-volatile solute reduces vapour pressure because","options":["the mole fraction of solvent molecules at the surface falls","the solute evaporates faster than the solvent","$K_H$ becomes infinite","the solution must freeze"],"answer_index":0,"explanation":"Fewer solvent molecules occupy the surface, so the escape rate into the vapour falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-195","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"In the dilute limit the vapour pressure of a solution of a non-volatile solute is $p^\\circ$ multiplied by","options":["the mole fraction of the solvent","the mole fraction of the solute","the molality","$1 - M$"],"answer_index":0,"explanation":"$p = p^\\circ x_{\\mathrm{solvent}}$ is Raoult’s law for the solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
